import React from 'react';
import {useState} from 'react'
const LoginPage = () => {
const[name,setName]=useState("");
const[email,setEmail]=useState("");
const[phone,setPhone]=useState(0);
const[age,setAge]=useState(0);
const[password,setPassword]=useState("");





    const submit=async (e)=>{
        e.preventDefault()
    const userdetails={name,email,phone,age,password};
    try{
    const api="http://localhost:5500/employees/add-employee"
    const res=await fetch(api,
              { method:"POST",
                headers:{
               "Content-Type":'application/json'},
               body:JSON.stringify(userdetails)
            }
        )

       await fetch
    }
    catch(error){
        alert("error to submit")
    }
}
    
  return (
    <div>
      <div>
        <form onSubmit={submit}>
            <label>UserName</label>
            <input type="text" name="name" placeholder='Username' onChange={(e)=>setName(e.target.value)}/><br />
            <label>Email</label>
            <input type="email"name="email" placeholder='Email'onChange={(e)=>setEmail(e.target.value)}/><br />
            <label>Phone</label>
            <input type="tel"name="phone" placeholder='PhoneNumber'onChange={(e)=>setPhone(e.target.value)}/><br />
            <label>age</label>
            <input type="number"name="age" placeholder='age'onChange={(e)=>setAge(e.target.value)}/><br />
            <label>Password</label>
            <input type="text" name="password" placeholder='Password'onChange={(e)=>setPassword(e.target.value)}/><br />
            <button type='submit'>Submit</button>
        </form>
      </div>
      <div>
            
      </div>
    </div>
  );
}

export default LoginPage;
